import{_ as a,C as s,o,c as r,j as t,a as i,E as h,a6 as p}from"./chunks/framework.CCKCzdWs.js";const f=JSON.parse('{"title":"Run on my machine","description":"Ask the desktop app on your own machine to run Playwright tests from the dashboard: who may ask, how an administrator turns it on, Connected apps, and why a requested run is yours alone.","frontmatter":{"title":"Run on my machine","description":"Ask the desktop app on your own machine to run Playwright tests from the dashboard: who may ask, how an administrator turns it on, Connected apps, and why a requested run is yours alone.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-on-my-machine.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-on-my-machine.html"}],["meta",{"property":"og:title","content":"Run on my machine | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Ask the desktop app on your own machine to run Playwright tests from the dashboard: who may ask, how an administrator turns it on, Connected apps, and why a requested run is yours alone."}]]},"headers":[],"relativePath":"features/run-on-my-machine.md","filePath":"features/run-on-my-machine.md","lastUpdated":1794391900000}'),d={name:"features/run-on-my-machine.md"};function c(l,e,u,m,y,w){const n=s("Needs");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"run-on-my-machine",tabindex:"-1"},[i("Run on my machine "),t("a",{class:"header-anchor",href:"#run-on-my-machine","aria-label":'Permalink to "Run on my machine"'},"​")],-1)),h(n,{desktop:"",admin:""}),e[1]||(e[1]=p('<p>Run on my machine lets a signed-in person ask the desktop app on their own machine to run tests they found on the dashboard. The instance carries the request; the app asks them before every run, in its own window, and runs the tests in their own folder. The run it starts reports back to the instance as a <strong>requested run</strong>: theirs alone, and kept out of everything the team sees.</p><h2 id="experimental" tabindex="-1">Experimental <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;Experimental&quot;">​</a></h2><p><strong>Experimental.</strong> Run on my machine is off by default, and the desktop app is the one app that takes requests in this release. The design is in the <a href="https://github.com/PiwiTests/piwi/blob/main/proposals/run-on-my-machine.md" target="_blank" rel="noreferrer">Run on my machine design record</a>.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>An administrator turns it on in <strong>Settings → Capabilities → Off until turned on → Run on my machine → Turn on</strong>, and off the same way. It needs <a href="/operate/authentication.html">sign-in</a> turned on: a request belongs to the person who made it, so an instance without accounts refuses it. A project admin declines it for one project in <strong>Project → Settings → Capabilities</strong>, which lists it while the instance has it on.</p><p>Turned off or declined, the instance refuses every request for that project, and a connected app receives none.</p><h2 id="who-may-ask" tabindex="-1">Who may ask <a class="header-anchor" href="#who-may-ask" aria-label="Permalink to &quot;Who may ask&quot;">​</a></h2><ul><li><strong>Contributors and up</strong> may ask (<code>run:request</code>), on the projects where they hold the role. A Contributor cannot submit a run with an API key; a requested run does not need to, since its app reports it with a credential that starts that one run.</li><li><strong>Only a signed-in session</strong> creates a request: never an API key, a CI job or an MCP client.</li><li><strong>A request goes only to the person&#39;s own apps</strong>, which take it only on projects where they may run tests.</li></ul><h2 id="connect-the-desktop-app" tabindex="-1">Connect the desktop app <a class="header-anchor" href="#connect-the-desktop-app" aria-label="Permalink to &quot;Connect the desktop app&quot;">​</a></h2><p>In Piwi Desktop, open <strong>Settings → Desktop app → Run on my machine</strong>, enter the instance&#39;s address and click <strong>Connect</strong>. The app opens the instance&#39;s page, which asks you to allow <strong>Piwi Desktop</strong> with the code the app shows. Once allowed, the app keeps its key in the operating system&#39;s keychain (Keychain on macOS, Credential Manager on Windows, the Secret Service on Linux), never in a file, and holds its connection to the instance open while it runs. An app connects to one instance at a time. <strong>Disconnect</strong> removes the key from the keychain; the app stays listed in the instance&#39;s Connected apps until you revoke it there.</p><p>The folder of each project is linked on this machine, per instance: the first request for a project asks for it, and <strong>Settings → Desktop app</strong> lists the linked folders, with <strong>Unlink</strong>.</p><h2 id="ask-for-a-run" tabindex="-1">Ask for a run <a class="header-anchor" href="#ask-for-a-run" aria-label="Permalink to &quot;Ask for a run&quot;">​</a></h2><p><strong>Run on my machine</strong> shows on a run&#39;s page (its failed tests, or all of them), on an execution&#39;s page and on a test&#39;s page (that test) while the capability is on for the project and you may ask there. Its window picks what runs, which of your apps runs it, and the run options of <strong>Copy retry command</strong>: headed, trace, repeat each, workers and, when the tests ran in more than one, the Playwright project. A request holds at most 200 tests; a test with no recorded line is left out, and the window says how many. Nobody else&#39;s app receives it.</p><h2 id="in-the-app" tabindex="-1">In the app <a class="header-anchor" href="#in-the-app" aria-label="Permalink to &quot;In the app&quot;">​</a></h2><p>The request opens the desktop app&#39;s window, in front: the instance that asked, the tests, the checks of the linked folder, and the exact command. Nothing runs until you click <strong>Run</strong>:</p><ul><li><strong>The folder</strong>: linked, with a Playwright config and <code>@playwright/test</code> installed, and every spec of the request inside it.</li><li><strong>The commit</strong>: the run&#39;s branch and commit against the folder&#39;s. On another commit, or with uncommitted changes, the tests are picked by their titles (<code>--grep</code>) rather than by their lines, which may have moved.</li></ul><p><strong>Not now</strong> declines it, or refuses it with the checks that failed, and the page says which. A request nobody answers in the app within 10 minutes ends.</p><p>The app takes the command and a key for this one run from its own server, never from the page or the window. The run reports to the instance that asked with that key, which starts one run within 30 minutes and nothing else, whatever server the Playwright config names. It shows in the app&#39;s Local runs while it goes on.</p><h2 id="follow-and-stop" tabindex="-1">Follow and stop <a class="header-anchor" href="#follow-and-stop" aria-label="Permalink to &quot;Follow and stop&quot;">​</a></h2><p>Once sent, the same window follows the request: waiting for your app, shown in the app, running, ended with its outcome, and a link to its run. <strong>Stop</strong> ends it from the page: the app stops the run, or drops a request it has not run. <strong>Run again</strong> sends the same tests with the same options. <strong>Settings → Account → Your runs on my machine</strong> lists your last 20 requests, with <strong>Stop</strong> for one still going on.</p><h2 id="what-leaves-your-machine" tabindex="-1">What leaves your machine <a class="header-anchor" href="#what-leaves-your-machine" aria-label="Permalink to &quot;What leaves your machine&quot;">​</a></h2><p>The run&#39;s results, as any run reports them: the tests, their steps, errors, attachments, traces and reports, sent to the instance that asked and seen by you alone. For a requested run, the reporter sends no coverage, test manifest, code reach or environment details, AI steps only replay, and the run stays out of the desktop app&#39;s own dashboard. The instance never keeps it forever.</p><p>The app starts the run with <code>PIWI_REQUEST_INSTANCE</code>, the instance that asked, and <code>PIWI_REQUEST_TOKEN_FILE</code>, a file only you can read that holds the key of that one run. The reporter and its workers send the run there with that key, whatever server and credentials the config names. A file that is missing or holds no key turns the reporter off for the run, and it says why; on macOS and Linux, so does a file others can read.</p><h2 id="connected-apps" tabindex="-1">Connected apps <a class="header-anchor" href="#connected-apps" aria-label="Permalink to &quot;Connected apps&quot;">​</a></h2><p><strong>Settings → Account → Connected apps</strong> lists the apps you connected from their own window: Piwi Picker, an editor, the desktop app. Each shows when it connected and, for an app that runs tests, <strong>Online now</strong> while it holds its connection to the instance open and has called the instance within the last two minutes, or else when it was last seen. <strong>Revoke</strong> disconnects one: the instance closes the connection of an app that runs tests at once, and refuses its next call. An administrator sees the same list for any user in <strong>Settings → Users → API keys</strong>. The keys these apps hold are not listed under API keys.</p><p>The instance sends a connected app each request as it is made, on that connection, with the time it stops waiting, and the requests still waiting each time the app connects again. When a waiting request is stopped, or another of your apps takes it, the instance tells the others to drop it. An app can also ask for its requests instead, where a proxy cuts long connections.</p><h2 id="a-requested-run-is-yours-alone" tabindex="-1">A requested run is yours alone <a class="header-anchor" href="#a-requested-run-is-yours-alone" aria-label="Permalink to &quot;A requested run is yours alone&quot;">​</a></h2><p>A requested run shows to the person who asked for it, and to nobody else:</p><ul><li><strong>Its own page</strong> opens for you, and reads as not found for anyone else, as its executions, its attachments, its traces and its reports do.</li><li><strong>The test&#39;s recent executions</strong> list it for you, marked <strong>On your machine</strong>. The test&#39;s pass rate, flaky score and history leave it out.</li><li><strong>No list a project&#39;s members read</strong> shows it: the project&#39;s runs, search, analytics, the MCP tools.</li><li><strong>With sign-in turned off, or once its requester is deleted</strong>, nobody sees it.</li></ul><p>It was run to look, on a branch and a machine the team did not choose, so it stays out of everything the team sees: no failure clusters, flakiness, analytics or baselines; no notifications, pull-request comments or tracker writes; no coverage, and it never sets the project&#39;s default branch. It is never kept forever: retention removes it, and you can delete it yourself from its page. Someone who holds <code>run:delete</code> on the project can delete it through the API without seeing it.</p><p>A <a href="./share-links.html">share link</a> you make for one of its executions opens for whoever has the link, as any share link does, so you can show a teammate what happened on your machine. It appears in the project&#39;s list of share links.</p><h2 id="one-instance-one-replica" tabindex="-1">One instance, one replica <a class="header-anchor" href="#one-instance-one-replica" aria-label="Permalink to &quot;One instance, one replica&quot;">​</a></h2><p>Whether an app is online is held in the server&#39;s memory, as live run updates are. The instance runs as one replica, as the <a href="/operate/deployment.html">deployment page</a> requires.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./desktop.html">Desktop app</a>: the app that takes requests, and its Settings page</li><li><a href="./desktop-runs.html">Desktop app runs</a>: the runs the desktop app starts and how you follow them</li><li><a href="./share-links.html">Share links</a>: showing one execution to someone without an account</li></ul>',35))])}const k=a(d,[["render",c]]);export{f as __pageData,k as default};
